def compare_rle_streams(stream_a, stream_b, escape_tok):
    def dec(toks):
        out = []
        i = 0
        while i < len(toks):
            if toks[i] == escape_tok:
                out.extend([toks[i + 1]] * toks[i + 2])
                i += 3
            else:
                out.append(toks[i])
                i += 1
        return out
    a, b = dec(stream_a), dec(stream_b)
    m = min(len(a), len(b))
    for k in range(m):
        if a[k] != b[k]:
            return [len(a), len(b), k]
    return [len(a), len(b), -1 if len(a) == len(b) else m]

